import 'widgets/widgets.dart';

class NewsListPage extends StatefulWidget {
  const NewsListPage({super.key});

  @override
  State<NewsListPage> createState() => _NewsListPageState();
}

class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
  static final _tween = Tween<double>(begin: 0.25, end: 1);

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation;

  /// Новости, которые уже можно показывать: кэш, а затем ответ сети.
  List<NewsModel>? _newsList;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _scaleController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _scaleController = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 200),
    );
    _scaleAnimation = _tween.animate(_scaleController);
  }

  /// Cache-then-network: сначала мгновенно отдаём кэш, параллельно запрашиваем
  /// сеть и обновляем список, когда придёт ответ.
  void _initData() {
    final NewsRepository newsRepository = context.read<NewsRepository>();

    newsRepository.getCachedNewsFeed(NewsFeedFilter.all).then((List<NewsModel> cached) {
      _showNews(cached);
    }).catchError((Object _) {
      // Кэш недоступен — ждём ответ сети.
    });

    newsRepository.refreshNewsFeed(NewsFeedFilter.all).then((List<NewsModel> fresh) {
      _showNews(fresh);
    }).catchError((Object _) {
      // Сеть недоступна — остаёмся на кэше.
    });
  }

  void _showNews(List<NewsModel> value) {
    if (!mounted) return;

    setState(() => _newsList = value);

    _scaleController.forward(); // запускаем анимацию
  }

  @override
  Widget build(BuildContext context) {
    final List<NewsModel>? data = _newsList;
    if (data == null) return const Scaffold(body: SizedBox.shrink());

    return Scaffold(
      appBar: AppBar(title: Text(context.loc.news)),
      body: ScaleTransition(
        scale: _scaleAnimation,
        child: ListView.builder(
          itemCount: data.length,
          itemBuilder: (BuildContext context, int index) {
            final NewsModel news = data[index];

            return Padding(
              key: ValueKey(news.link),
              padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
              child: NewsCard(model: news),
            );
          },
          padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
        ),
      ),
    );
  }
}
