import '../mocks/repository.mocks.dart';

import 'widget.dart';

Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('NewsListPage', () {
    final MockNewsRepositoryV2 mockNewsRepository = MockNewsRepositoryV2();

    final cachedItems = [
      NewsModel(title: 'Из кэша', link: 'https://example.com/cached', date: DateTime.now()),
    ];

    final freshItems = [
      NewsModel(title: 'Заголовок 1', link: 'https://example.com/1', date: DateTime.now()),
      NewsModel(title: 'Заголовок 2', link: 'https://example.com/2', date: DateTime.now()),
    ];

    setUp(() {
      when(mockNewsRepository.getCachedNewsFeed(any)).thenAnswer((_) async => cachedItems);
      when(mockNewsRepository.refreshNewsFeed(any)).thenAnswer((_) async => freshItems);
    });

    Widget newsListWidget() => buildWidget(
          providers: [
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const NewsListPage(),
        );

    testWidgets('should display all news items when loaded', (WidgetTester tester) async {
      await tester.pumpWidget(newsListWidget());

      await tester.pumpAndSettle();

      expect(find.text('Заголовок 1'), findsOneWidget);
      expect(find.text('Заголовок 2'), findsOneWidget);
      expect(find.text('Заголовок 3'), findsNothing);
    });

    testWidgets('should show cached news before network response arrives', (WidgetTester tester) async {
      final Completer<List<NewsModel>> networkResponse = Completer<List<NewsModel>>();
      when(mockNewsRepository.refreshNewsFeed(any)).thenAnswer((_) => networkResponse.future);

      await tester.pumpWidget(newsListWidget());
      await tester.pump();

      expect(find.text('Из кэша'), findsOneWidget);
      expect(find.text('Заголовок 1'), findsNothing);

      networkResponse.complete(freshItems);
      await tester.pumpAndSettle();

      expect(find.text('Из кэша'), findsNothing);
      expect(find.text('Заголовок 1'), findsOneWidget);
    });

    testWidgets('should keep cached news when network request fails', (WidgetTester tester) async {
      when(mockNewsRepository.refreshNewsFeed(any)).thenAnswer((_) => Future<List<NewsModel>>.error(Exception('network')));

      await tester.pumpWidget(newsListWidget());
      await tester.pumpAndSettle();

      expect(find.text('Из кэша'), findsOneWidget);
      expect(tester.takeException(), isNull);
    });
  });
}
